 #[test]fn alias_sort_reuse_requires_both_source_admission_and_complete_result_retention(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=alias(&c,0,ExprId(2));let first=c.infer_exact_closure_in_context(&t,&[],&mut 4096,0);assert!(matches!(first,Some(TypeValue::Sort(_))));let mut work=1;assert_eq!(c.infer_exact_closure_in_context(&t,&[],&mut work,0),first,"both alias admission and completed Sort retention are required");assert_eq!(work,0);}
